"""Turning generated bytes into something Python can call.

The sequence is: generate once against a placeholder address to learn the code
size, map one region big enough for the class table plus the code, generate
again against the table's real address, write both halves, flip the mapping to
read+execute, and hand out a ``ctypes`` function pointer into it.

The second generation pass is asserted to be the same length as the first. If
that ever fails, an address-dependent instruction has crept into the generator
and the mapping would be sized wrong -- better to hear about it here than to
execute off the end of a page.
"""

import ctypes

from . import codegen, disasm, memory


class Program(object):
    """A compiled DFA, live in executable memory.

    ``call(subject)`` answers the same question as the interpreted tiers: does
    this pattern match. The mapping is released when the object is dropped, so a
    :class:`Program` owns its memory rather than leaking a page per pattern --
    which matters, because the policy experiments compile thousands of them.
    """

    def __init__(self, dfa, abi="sysv"):
        size = codegen.code_size(dfa, abi=abi)
        self.block = memory.ExecutableBlock(codegen.CODE_OFFSET + size)
        self.table_addr = self.block.addr + codegen.DATA_OFFSET
        self.code = codegen.compile_to_bytes(dfa, self.table_addr, abi=abi)
        if len(self.code) != size:
            self.block.free()
            raise AssertionError(
                "code size changed between passes (%d -> %d): the generator "
                "emitted something address-dependent" % (size, len(self.code)))

        self.block.write(codegen.DATA_OFFSET, codegen.class_table(dfa))
        self.block.write(codegen.CODE_OFFSET, self.code)
        self.block.make_executable()
        self.fn = self.block.function(
            codegen.CODE_OFFSET, ctypes.c_int,
            [ctypes.c_char_p, ctypes.c_size_t])
        self.n_states = len(dfa)

    def __call__(self, subject):
        # ``c_char_p`` hands the CPU a pointer to the bytes object's own
        # storage. Copying into a buffer first -- the obvious way -- costs more
        # than the match does above a few kilobytes, and turns a measurement of
        # generated code into a measurement of memcpy. The length is passed
        # separately, so embedded NULs are not a problem.
        if not isinstance(subject, bytes):
            subject = bytes(subject)
        return bool(self.fn(subject, len(subject)))

    def code_bytes(self):
        return self.code

    def listing(self, dfa=None, abi="sysv"):
        """The generated code, decoded from the bytes that were written.

        Deliberately decoded rather than echoed from the assembler's own
        listing: what this prints is what the CPU will see.
        """
        a = codegen.generate(dfa, self.table_addr, abi=abi) if dfa else None
        labels = a.labels if a else None
        return disasm.disassemble(self.code, labels)

    def free(self):
        self.block.free()


def compile_dfa(dfa, abi="sysv"):
    return Program(dfa, abi=abi)


def listing_for(dfa, table_addr=0x0, abi="sysv"):
    """Disassemble a DFA's code without executing -- or mapping -- anything.

    This is the path that works on any machine: it needs no ``mmap``, no
    ``PROT_EXEC``, and no x86 CPU. On a Windows laptop you can still read
    exactly what hotpath would emit.
    """
    a = codegen.generate(dfa, table_addr, abi=abi)
    return disasm.disassemble(a.assemble(), a.labels)
